// dsig_p1_wrap.sv - testbench wrapper of phase 1 of the digital signature IP.
// It connects the generated CSR, the control block and the buffer as section 11.3 (CSR connection
// to the design) and section 14.2 (hierarchy) of the specification describe. It is test code and
// not part of the delivered RTL: the structural top m_vlsit_dsig_top replaces it in a later phase.
// The ports that the key, random, engine and hash blocks would drive are ports of this wrapper, so
// that the behavioral models of the testbench can drive them.
`timescale 1ns/1ps

module dsig_p1_wrap #(
  parameter logic [31:0] PARA_CSR_ASYNC     = 1,
  parameter logic [31:0] PARA_CAP_ALG       = 32'h7FFF,
  parameter logic [31:0] PARA_CAP_KGEN      = 32'h0FFF,
  parameter logic [31:0] PARA_CAP_SIGN      = 32'h0FFF,
  parameter logic [31:0] PARA_CAP_VRFY      = 32'h7FFF,
  parameter logic [31:0] PARA_EN_PURE       = 1,
  parameter logic [31:0] PARA_EN_PREHASH    = 1,
  parameter logic [31:0] PARA_EN_LOCK       = 1,
  parameter logic [31:0] PARA_EN_LOG        = 1,
  parameter logic [31:0] PARA_EN_VAS        = 1,
  parameter logic [31:0] PARA_EN_HYBRID     = 1,
  parameter logic [31:0] PARA_EN_DPA_EC     = 0,
  parameter logic [31:0] PARA_EN_DPA_PQ     = 0,
  parameter logic [31:0] PARA_ECDSA_NONCE   = 2,
  parameter logic [31:0] PARA_BUF_BYTES     = 1024,
  parameter logic [31:0] PARA_AXI_DW        = 64,
  parameter logic [31:0] PARA_SLHDSA_SETS   = 32'h001,
  parameter logic [31:0] PARA_LMS_SETS      = 32'h00001,
  parameter logic [31:0] PARA_LMOTS_SETS    = 32'h0001,
  parameter logic [31:0] PARA_XMSS_SETS_LO  = 32'h00000001,
  parameter logic [31:0] PARA_XMSS_SETS_HI  = 32'h000
) (
  // Clocks and resets
  input  wire        i_clk_apb,
  input  wire        i_rst_n_apb,
  input  wire        i_clk_core,
  input  wire        i_rst_n_core,

  // APB4 completer port of the CSR
  input  wire        i_apb_psel,
  input  wire        i_apb_penable,
  input  wire        i_apb_pwrite,
  input  wire [15:0] i_apb_paddr,
  input  wire [31:0] i_apb_pwdata,
  input  wire [3:0]  i_apb_pstrb,
  input  wire [2:0]  i_apb_pprot,
  output wire        o_apb_pready,
  output wire        o_apb_pslverr,
  output wire [31:0] o_apb_prdata,
  input  wire        i_protect_en,
  input  wire        i_slverr_en,

  // Buffer port of the bus side (stand-in for the AXI4 block)
  input  wire        i_axi_wr_en,
  input  wire [6:0]  i_axi_wr_addr,
  input  wire [63:0] i_axi_wr_data,
  input  wire [7:0]  i_axi_wr_strb,
  output wire        o_axi_wr_rej,
  input  wire        i_axi_rd_en,
  input  wire [6:0]  i_axi_rd_addr,
  output wire [63:0] o_axi_rd_data,
  output wire        o_axi_rd_valid,
  output wire        o_axi_rd_rej,

  // Buffer port of the engines
  input  wire        i_eng_rd_en,
  input  wire [6:0]  i_eng_rd_addr,
  output wire [63:0] o_eng_rd_data,
  output wire        o_eng_rd_valid,
  input  wire        i_eng_wr_en,
  input  wire [6:0]  i_eng_wr_addr,
  input  wire [63:0] i_eng_wr_data,
  input  wire [7:0]  i_eng_wr_strb,

  // Handshakes with the engines, key, random and verify-after-sign blocks
  output wire [2:0]  o_eng_start,
  input  wire        i_eng_done,
  input  wire        i_eng_err,
  input  wire [11:0] i_eng_err_flags,
  input  wire        i_eng_sigok,
  output wire        o_key_start,
  input  wire        i_key_done,
  input  wire        i_key_tmo,
  output wire        o_rng_start,
  input  wire        i_rng_done,
  input  wire        i_rng_tmo,
  output wire        o_vas_start,
  input  wire        i_vas_done,
  input  wire        i_vas_ok,
  output wire        o_zero,
  input  wire        i_zero_done,
  input  wire        i_rng_due,
  input  wire        i_rng_ready,
  input  wire        i_rng_reseed_clr,
  output wire        o_rng_reseed,
  output wire [15:0] o_tmo_key,
  output wire [15:0] o_tmo_ent,

  // Interrupt and alarm outputs
  output wire        o_irq,
  output wire        o_alarm
);

  // Signals between the blocks
  wire        w_ctrl_en;
  wire [14:0] w_alg_en;
  wire [14:0] w_alg_act;
  wire        w_lock_req;
  wire        w_lock_req_clr;
  wire        w_locked;
  wire [3:0]  w_op_alg;
  wire [1:0]  w_op_op;
  wire [1:0]  w_op_form;
  wire        w_op_hedged;
  wire [1:0]  w_op_nonce;
  wire [2:0]  w_op_hash;
  wire [1:0]  w_op_hybpol;
  wire [3:0]  w_set_slh;
  wire [4:0]  w_set_lmstype;
  wire [3:0]  w_set_lmots;
  wire [3:0]  w_set_hsslvl;
  wire [5:0]  w_set_xmss;
  wire [31:0] w_len_msg;
  wire [7:0]  w_len_ctx;
  wire [16:0] w_off_msg;
  wire [16:0] w_off_sig;
  wire [16:0] w_off_pk;
  wire [16:0] w_off_res;
  wire        w_cmd_start;
  wire        w_cmd_abort;
  wire        w_cmd_clr;
  wire        w_cmd_start_clr;
  wire        w_cmd_abort_clr;
  wire        w_cmd_clr_clr;
  wire        w_sts_busy;
  wire        w_sts_resvld;
  wire        w_sts_sigok;
  wire        w_sts_edok;
  wire        w_sts_mlok;
  wire [11:0] w_err_set;
  wire [2:0]  w_alarm_set;
  wire [2:0]  w_alarm_flags;
  wire [2:0]  w_irq_raw;
  wire [2:0]  w_irq_en;
  wire [2:0]  w_irq_inj;
  wire [2:0]  w_irq_raw_set;
  wire        w_flags_clr;
  wire [2:0]  w_irq_sts;
  wire        w_log_lock_req;
  wire        w_log_lock_clr;
  wire        w_log_locked;
  wire [31:0] w_cnt_ops;
  wire [31:0] w_cnt_fail;
  wire        w_busy;
  wire        w_buf_err_ovf;
  wire        w_buf_err_busy;
  wire        w_reg_rd_en;
  wire [15:0] w_reg_rd_addr;
  wire        w_reg_wr_en;
  wire [15:0] w_reg_wr_addr;
  wire [31:0] w_win_wr_data;
  wire [16:0] w_win_addr;
  wire        w_win_addr_we;
  wire [16:0] w_win_addr_wdata;
  wire [31:0] w_win_rd_data;
  wire [31:0] w_key [0:16];
  wire [3:0]  w_run_alg;
  wire [1:0]  w_run_op;

  // Constant capability words derived from the parameters (section 11.3)
  localparam logic [31:0] LPARA_FEAT_FIXED = 32'h0000_007C;

  // Generated CSR (clock of the registers is the core clock)
  m_vlsit_csr_dsig #(
    .PARA_ASYNCHRONOUS (PARA_CSR_ASYNC)
  ) u_csr (
    .i_clk_apb         (i_clk_apb),
    .i_rst_n_apb       (i_rst_n_apb),
    .i_clk_reg         (i_clk_core),
    .i_rst_n_reg       (i_rst_n_core),
    .i_apb_psel        (i_apb_psel),
    .i_apb_penable     (i_apb_penable),
    .i_apb_pwrite      (i_apb_pwrite),
    .i_apb_paddr       (i_apb_paddr),
    .i_apb_pwdata      (i_apb_pwdata),
    .i_apb_pstrb       (i_apb_pstrb),
    .i_apb_pprot       (i_apb_pprot),
    .o_apb_pready      (o_apb_pready),
    .o_apb_pslverr     (o_apb_pslverr),
    .o_apb_prdata      (o_apb_prdata),
    .i_protect_en      (i_protect_en),
    .i_slverr_en       (i_slverr_en),
    .o_reg_rd_en       (w_reg_rd_en),
    .o_reg_rd_addr     (w_reg_rd_addr),
    .o_reg_wr_en       (w_reg_wr_en),
    .o_reg_wr_addr     (w_reg_wr_addr),
    .i_dsig_version_major (16'd1),
    .i_dsig_version_minor (16'd0),
    // Capability of algorithms: index order ed25519, ed25519ctx, ed25519ph, ed448, ed448ph,
    // p256, p384, p521, k256, mldsa44, mldsa65, mldsa87, slhdsa, lms, xmss
    .i_dsig_cap_alg_ed25519    (PARA_CAP_ALG[0]),
    .i_dsig_cap_alg_ed25519ctx (PARA_CAP_ALG[1]),
    .i_dsig_cap_alg_ed25519ph  (PARA_CAP_ALG[2]),
    .i_dsig_cap_alg_ed448      (PARA_CAP_ALG[3]),
    .i_dsig_cap_alg_ed448ph    (PARA_CAP_ALG[4]),
    .i_dsig_cap_alg_p256       (PARA_CAP_ALG[5]),
    .i_dsig_cap_alg_p384       (PARA_CAP_ALG[6]),
    .i_dsig_cap_alg_p521       (PARA_CAP_ALG[7]),
    .i_dsig_cap_alg_k256       (PARA_CAP_ALG[8]),
    .i_dsig_cap_alg_mldsa44    (PARA_CAP_ALG[9]),
    .i_dsig_cap_alg_mldsa65    (PARA_CAP_ALG[10]),
    .i_dsig_cap_alg_mldsa87    (PARA_CAP_ALG[11]),
    .i_dsig_cap_alg_slhdsa     (PARA_CAP_ALG[12]),
    .i_dsig_cap_alg_lms        (PARA_CAP_ALG[13]),
    .i_dsig_cap_alg_xmss       (PARA_CAP_ALG[14]),
    .i_dsig_cap_kgen_ed25519    (PARA_CAP_KGEN[0]),
    .i_dsig_cap_kgen_ed25519ctx (PARA_CAP_KGEN[1]),
    .i_dsig_cap_kgen_ed25519ph  (PARA_CAP_KGEN[2]),
    .i_dsig_cap_kgen_ed448      (PARA_CAP_KGEN[3]),
    .i_dsig_cap_kgen_ed448ph    (PARA_CAP_KGEN[4]),
    .i_dsig_cap_kgen_p256       (PARA_CAP_KGEN[5]),
    .i_dsig_cap_kgen_p384       (PARA_CAP_KGEN[6]),
    .i_dsig_cap_kgen_p521       (PARA_CAP_KGEN[7]),
    .i_dsig_cap_kgen_k256       (PARA_CAP_KGEN[8]),
    .i_dsig_cap_kgen_mldsa44    (PARA_CAP_KGEN[9]),
    .i_dsig_cap_kgen_mldsa65    (PARA_CAP_KGEN[10]),
    .i_dsig_cap_kgen_mldsa87    (PARA_CAP_KGEN[11]),
    .i_dsig_cap_kgen_slhdsa     (PARA_CAP_KGEN[12]),
    .i_dsig_cap_kgen_lms        (PARA_CAP_KGEN[13]),
    .i_dsig_cap_kgen_xmss       (PARA_CAP_KGEN[14]),
    .i_dsig_cap_sign_ed25519    (PARA_CAP_SIGN[0]),
    .i_dsig_cap_sign_ed25519ctx (PARA_CAP_SIGN[1]),
    .i_dsig_cap_sign_ed25519ph  (PARA_CAP_SIGN[2]),
    .i_dsig_cap_sign_ed448      (PARA_CAP_SIGN[3]),
    .i_dsig_cap_sign_ed448ph    (PARA_CAP_SIGN[4]),
    .i_dsig_cap_sign_p256       (PARA_CAP_SIGN[5]),
    .i_dsig_cap_sign_p384       (PARA_CAP_SIGN[6]),
    .i_dsig_cap_sign_p521       (PARA_CAP_SIGN[7]),
    .i_dsig_cap_sign_k256       (PARA_CAP_SIGN[8]),
    .i_dsig_cap_sign_mldsa44    (PARA_CAP_SIGN[9]),
    .i_dsig_cap_sign_mldsa65    (PARA_CAP_SIGN[10]),
    .i_dsig_cap_sign_mldsa87    (PARA_CAP_SIGN[11]),
    .i_dsig_cap_sign_slhdsa     (PARA_CAP_SIGN[12]),
    .i_dsig_cap_sign_lms        (PARA_CAP_SIGN[13]),
    .i_dsig_cap_sign_xmss       (PARA_CAP_SIGN[14]),
    .i_dsig_cap_vrfy_ed25519    (PARA_CAP_VRFY[0]),
    .i_dsig_cap_vrfy_ed25519ctx (PARA_CAP_VRFY[1]),
    .i_dsig_cap_vrfy_ed25519ph  (PARA_CAP_VRFY[2]),
    .i_dsig_cap_vrfy_ed448      (PARA_CAP_VRFY[3]),
    .i_dsig_cap_vrfy_ed448ph    (PARA_CAP_VRFY[4]),
    .i_dsig_cap_vrfy_p256       (PARA_CAP_VRFY[5]),
    .i_dsig_cap_vrfy_p384       (PARA_CAP_VRFY[6]),
    .i_dsig_cap_vrfy_p521       (PARA_CAP_VRFY[7]),
    .i_dsig_cap_vrfy_k256       (PARA_CAP_VRFY[8]),
    .i_dsig_cap_vrfy_mldsa44    (PARA_CAP_VRFY[9]),
    .i_dsig_cap_vrfy_mldsa65    (PARA_CAP_VRFY[10]),
    .i_dsig_cap_vrfy_mldsa87    (PARA_CAP_VRFY[11]),
    .i_dsig_cap_vrfy_slhdsa     (PARA_CAP_VRFY[12]),
    .i_dsig_cap_vrfy_lms        (PARA_CAP_VRFY[13]),
    .i_dsig_cap_vrfy_xmss       (PARA_CAP_VRFY[14]),
    .i_dsig_cap_slh_sets   (PARA_SLHDSA_SETS[11:0]),
    .i_dsig_cap_lms_lms    (PARA_LMS_SETS[19:0]),
    .i_dsig_cap_xmss_sets  (PARA_XMSS_SETS_LO),
    .i_dsig_cap_xmssh_sets (PARA_XMSS_SETS_HI[11:0]),
    .i_dsig_cap_lmots_lmots (PARA_LMOTS_SETS[15:0]),
    .i_dsig_cap_feat_pure      (PARA_EN_PURE[0]),
    .i_dsig_cap_feat_prehash   (PARA_EN_PREHASH[0]),
    .i_dsig_cap_feat_axi       (LPARA_FEAT_FIXED[2]),
    .i_dsig_cap_feat_dma       (LPARA_FEAT_FIXED[3]),
    .i_dsig_cap_feat_win       (LPARA_FEAT_FIXED[4]),
    .i_dsig_cap_feat_keyif     (LPARA_FEAT_FIXED[5]),
    .i_dsig_cap_feat_keyreg    (LPARA_FEAT_FIXED[6]),
    .i_dsig_cap_feat_vas       (PARA_EN_VAS[0]),
    .i_dsig_cap_feat_dpa_ec    (PARA_EN_DPA_EC[0]),
    .i_dsig_cap_feat_dpa_pq    (PARA_EN_DPA_PQ[0]),
    .i_dsig_cap_feat_hybrid    (PARA_EN_HYBRID[0]),
    .i_dsig_cap_feat_log       (PARA_EN_LOG[0]),
    .i_dsig_cap_feat_lock      (PARA_EN_LOCK[0]),
    .i_dsig_cap_feat_rngsrc    (1'b0),
    .i_dsig_cap_feat_csrasync  (PARA_CSR_ASYNC[0]),
    .i_dsig_cap_buf_buf        (PARA_BUF_BYTES[16:0]),
    .i_dsig_cap_buf_mulw       (2'd0),
    .o_dsig_ctrl_en            (w_ctrl_en),
    .o_dsig_alg_en_ed25519     (w_alg_en[0]),
    .o_dsig_alg_en_ed25519ctx  (w_alg_en[1]),
    .o_dsig_alg_en_ed25519ph   (w_alg_en[2]),
    .o_dsig_alg_en_ed448       (w_alg_en[3]),
    .o_dsig_alg_en_ed448ph     (w_alg_en[4]),
    .o_dsig_alg_en_p256        (w_alg_en[5]),
    .o_dsig_alg_en_p384        (w_alg_en[6]),
    .o_dsig_alg_en_p521        (w_alg_en[7]),
    .o_dsig_alg_en_k256        (w_alg_en[8]),
    .o_dsig_alg_en_mldsa44     (w_alg_en[9]),
    .o_dsig_alg_en_mldsa65     (w_alg_en[10]),
    .o_dsig_alg_en_mldsa87     (w_alg_en[11]),
    .o_dsig_alg_en_slhdsa      (w_alg_en[12]),
    .o_dsig_alg_en_lms         (w_alg_en[13]),
    .o_dsig_alg_en_xmss        (w_alg_en[14]),
    .i_dsig_alg_act_ed25519    (w_alg_act[0]),
    .i_dsig_alg_act_ed25519ctx (w_alg_act[1]),
    .i_dsig_alg_act_ed25519ph  (w_alg_act[2]),
    .i_dsig_alg_act_ed448      (w_alg_act[3]),
    .i_dsig_alg_act_ed448ph    (w_alg_act[4]),
    .i_dsig_alg_act_p256       (w_alg_act[5]),
    .i_dsig_alg_act_p384       (w_alg_act[6]),
    .i_dsig_alg_act_p521       (w_alg_act[7]),
    .i_dsig_alg_act_k256       (w_alg_act[8]),
    .i_dsig_alg_act_mldsa44    (w_alg_act[9]),
    .i_dsig_alg_act_mldsa65    (w_alg_act[10]),
    .i_dsig_alg_act_mldsa87    (w_alg_act[11]),
    .i_dsig_alg_act_slhdsa     (w_alg_act[12]),
    .i_dsig_alg_act_lms        (w_alg_act[13]),
    .i_dsig_alg_act_xmss       (w_alg_act[14]),
    .i_dsig_lock_locked        (w_locked),
    .o_dsig_lock_req           (w_lock_req),
    .i_hw_clr_dsig_lock_req    (w_lock_req_clr),
    .o_dsig_op_hybpol          (w_op_hybpol),
    .o_dsig_op_hash            (w_op_hash),
    .o_dsig_op_nonce           (w_op_nonce),
    .o_dsig_op_hedged          (w_op_hedged),
    .o_dsig_op_form            (w_op_form),
    .o_dsig_op_op              (w_op_op),
    .o_dsig_op_alg             (w_op_alg),
    .o_dsig_set_xmss           (w_set_xmss),
    .o_dsig_set_hsslvl         (w_set_hsslvl),
    .o_dsig_set_lmots          (w_set_lmots),
    .o_dsig_set_lmstype        (w_set_lmstype),
    .o_dsig_set_slh            (w_set_slh),
    .o_dsig_len_msg_len        (w_len_msg),
    .o_dsig_len_ctx_len        (w_len_ctx),
    .o_dsig_off_msg_off        (w_off_msg),
    .o_dsig_off_sig_off        (w_off_sig),
    .o_dsig_off_pk_off         (w_off_pk),
    .o_dsig_off_res_off        (w_off_res),
    .o_dsig_cmd_clr            (w_cmd_clr),
    .i_hw_clr_dsig_cmd_clr     (w_cmd_clr_clr),
    .o_dsig_cmd_abort          (w_cmd_abort),
    .i_hw_clr_dsig_cmd_abort   (w_cmd_abort_clr),
    .o_dsig_cmd_start          (w_cmd_start),
    .i_hw_clr_dsig_cmd_start   (w_cmd_start_clr),
    .i_dsig_sts_mlok           (w_sts_mlok),
    .i_dsig_sts_edok           (w_sts_edok),
    .i_dsig_sts_sigok          (w_sts_sigok),
    .i_dsig_sts_resvld         (w_sts_resvld),
    .i_dsig_sts_busy           (w_sts_busy),
    // Error flags: bit n of the set vector of the control block is bit n of dsig_err
    .o_dsig_err_busycmd        (),
    .i_hw_wdata_dsig_err_busycmd (w_err_set[11]),
    .i_hw_we_dsig_err_busycmd  (w_err_set[11] | w_flags_clr),
    .o_dsig_err_lockv          (),
    .i_hw_wdata_dsig_err_lockv (w_err_set[10]),
    .i_hw_we_dsig_err_lockv    (w_err_set[10] | w_flags_clr),
    .o_dsig_err_vasmis         (),
    .i_hw_wdata_dsig_err_vasmis (w_err_set[9]),
    .i_hw_we_dsig_err_vasmis   (w_err_set[9] | w_flags_clr),
    .o_dsig_err_keytmo         (),
    .i_hw_wdata_dsig_err_keytmo (w_err_set[8]),
    .i_hw_we_dsig_err_keytmo   (w_err_set[8] | w_flags_clr),
    .o_dsig_err_enttmo         (),
    .i_hw_wdata_dsig_err_enttmo (w_err_set[7]),
    .i_hw_we_dsig_err_enttmo   (w_err_set[7] | w_flags_clr),
    .o_dsig_err_buserr         (),
    .i_hw_wdata_dsig_err_buserr (w_err_set[6]),
    .i_hw_we_dsig_err_buserr   (w_err_set[6] | w_flags_clr),
    .o_dsig_err_bufovf         (),
    .i_hw_wdata_dsig_err_bufovf (w_err_set[5]),
    .i_hw_we_dsig_err_bufovf   (w_err_set[5] | w_flags_clr),
    .o_dsig_err_badpt          (),
    .i_hw_wdata_dsig_err_badpt (w_err_set[4]),
    .i_hw_we_dsig_err_badpt    (w_err_set[4] | w_flags_clr),
    .o_dsig_err_badkey         (),
    .i_hw_wdata_dsig_err_badkey (w_err_set[3]),
    .i_hw_we_dsig_err_badkey   (w_err_set[3] | w_flags_clr),
    .o_dsig_err_badlen         (),
    .i_hw_wdata_dsig_err_badlen (w_err_set[2]),
    .i_hw_we_dsig_err_badlen   (w_err_set[2] | w_flags_clr),
    .o_dsig_err_opuns          (),
    .i_hw_wdata_dsig_err_opuns (w_err_set[1]),
    .i_hw_we_dsig_err_opuns    (w_err_set[1] | w_flags_clr),
    .o_dsig_err_algdis         (),
    .i_hw_wdata_dsig_err_algdis (w_err_set[0]),
    .i_hw_we_dsig_err_algdis   (w_err_set[0] | w_flags_clr),
    // Interrupt raw events: done [0], err [1], sec [2]
    .o_dsig_irq_raw_sec        (w_irq_raw[2]),
